@namespace sv_4db57563b75844ffbd3a225f19c52b6d.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var step = i;
            var status = step == CurrentStep ? "active"
                       : CompletedSteps.Contains(step) ? "completed"
                       : "pending";
            <li class="step-item @status">
                @if (CompletedSteps.Contains(step) && step != CurrentStep)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@StepNames[step]</span>
                    </button>
                }
                else
                {
                    <span class="step-button" aria-current="@(step == CurrentStep ? "step" : null)">
                        <span class="step-icon">@(step + 1)</span>
                        <span class="step-label">@StepNames[step]</span>
                    </span>
                }
            </li>
            @if (i < StepNames.Count - 1)
            {
                <li class="step-connector @(CompletedSteps.Contains(i) ? "completed" : "")" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

@namespace sv_4db57563b75844ffbd3a225f19c52b6d.Components.Pages.Apply

<div class="work-entry-form">
    <div class="form-row">
        <div class="form-group">
            <label>Company Name</label>
            <input type="text" value="@Entry.Company"
                   @onchange="e => UpdateEntry(Entry with { Company = e.Value?.ToString() ?? "" })" />
        </div>
        <div class="form-group">
            <label>Job Title</label>
            <input type="text" value="@Entry.Title"
                   @onchange="e => UpdateEntry(Entry with { Title = e.Value?.ToString() ?? "" })" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Start Date</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>
    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = e.Value?.ToString() ?? "" })"></textarea>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-danger" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null;

    private void UpdateEntry(WorkEntry updated) => OnEntryChanged.InvokeAsync(updated);

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        OnEntryChanged.InvokeAsync(updated);
    }
}

@namespace sv_4db57563b75844ffbd3a225f19c52b6d.Components.Pages.Apply

<div class="reference-form">
    <div class="form-row">
        <div class="form-group">
            <label>Name</label>
            <input type="text" value="@Entry.Name"
                   @onchange="e => Update(Entry with { Name = e.Value?.ToString() ?? "" })" />
        </div>
        <div class="form-group">
            <label>Relationship</label>
            <input type="text" value="@Entry.Relationship"
                   @onchange="e => Update(Entry with { Relationship = e.Value?.ToString() ?? "" })" />
        </div>
    </div>
    <div class="form-row">
        <div class="form-group">
            <label>Email</label>
            <input type="email" value="@Entry.Email"
                   @onchange="e => Update(Entry with { Email = e.Value?.ToString() ?? "" })" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Entry.Phone"
                   @onchange="e => Update(Entry with { Phone = e.Value?.ToString() ?? "" })" />
        </div>
    </div>
    @if (CanRemove)
    {
        <button type="button" class="btn-danger" @onclick="OnRemove">Remove</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public Reference Entry { get; set; } = default!;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void Update(Reference updated) => OnEntryChanged.InvokeAsync(updated);
}

