        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void UpdateText(string value)
    {
        CoverLetter = value.Length > MaxLength ? value[..MaxLength] : value;
    }

    private void HandleNext()
    {
        _validationError = null;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            _validationError = "Please write a cover letter before continuing.";
            return;
        }
        OnNext.InvokeAsync(CoverLetter);
    }
}
