    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Reference> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void UpdateEntry(int index, Reference updated)
    {
        Entries[index] = updated;
    }

    private void AddEntry()
    {
        if (Entries.Count < 3)
            Entries.Add(new Reference("", "", "", ""));
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 2)
            Entries.RemoveAt(index);
    }

    private void HandleNext()
    {
        _validationError = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Name) || string.IsNullOrWhiteSpace(entry.Email))
            {
                _validationError = "Each reference requires at least a name and email.";
                return;
            }
        }
        OnNext.InvokeAsync(new List<Reference>(Entries));
    }
}

