@namespace sv_4db57563b75844ffbd3a225f19c52b6d.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea rows="12" maxlength="@MaxLength" value="@CoverLetter"
                  @oninput="e => UpdateText(e.Value?.ToString() ?? "")"></textarea>
        <div class="char-count @(CoverLetter.Length >= MaxLength ? "at-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-error">@_validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void UpdateText(string value)
    {
        CoverLetter = value.Length > MaxLength ? value[..MaxLength] : value;
    }

    private void HandleNext()
    {
        _validationError = null;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            _validationError = "Please write a cover letter before continuing.";
            return;
        }
        OnNext.InvokeAsync(CoverLetter);
    }
}

