    private List<Reference> _references = new() { new("", "", "", ""), new("", "", "", "") };
    private string _coverLetter = "";

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        _personalInfo = info;
        _completedSteps.Add(0);
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntry> entries)
    {
        _workEntries = entries;
        _completedSteps.Add(1);
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> entries)
    {
        _references = entries;
        _completedSteps.Add(2);
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        _coverLetter = letter;
        _completedSteps.Add(3);
        _currentStep = 4;
    }

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
            _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }
}

