}

.btn-primary {
    padding: 0.6rem 1.5rem;
    background: #2563eb;
    color: white;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    cursor: pointer;
    font-weight: 500;
}

.btn-primary:hover {
    background: #1d4ed8;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    padding: 0.6rem 1.5rem;
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    cursor: pointer;
}

.btn-outline:hover {
    background: #f9fafb;
}

.btn-secondary {
    padding: 0.5rem 1rem;
    background: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    cursor: pointer;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e5e7eb;
}

