    font-size: 0.85rem;
    cursor: pointer;
}

.btn-danger:hover {
    background: #fee2e2;
}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.btn-link:hover {
    color: #1d4ed8;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Entry Cards */
.entry-card {
    border: 1px solid #e5e7eb;
    border-radius: 0.5rem;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-card h4 {
    margin: 0 0 0.75rem 0;
    color: #6b7280;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

