.validation-error {
    background: #fef2f2;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    border: 1px solid #fecaca;
    margin-top: 1rem;
    font-size: 0.9rem;
}

.field-error {
    color: #dc2626;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

/* Character Count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6b7280;
    margin-top: 0.3rem;
}

.char-count.at-limit {
    color: #dc2626;
    font-weight: 500;
}

