    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.3rem 1rem;
    margin: 0.75rem 0 0 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.9rem;
}

.review-section dd {
    margin: 0;
    color: #111827;
}

.review-entry {
    margin-top: 0.75rem;
    padding-top: 0.75rem;
    border-top: 1px solid #f3f4f6;
}

.review-entry:first-child {
    margin-top: 0.5rem;
    padding-top: 0;
    border-top: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9fafb;
