 @namespace sv_4db57563b75844ffbd3a225f19c52b6d.Components.Pages.Apply

 <div class="work-entry-form">
     <div class="form-row">
         <div class="form-group">
             <label>Company Name</label>
             <input type="text" value="@Entry.Company"
                    @onchange="e => UpdateEntry(Entry with { Company = e.Value?.ToString() ?? string.Empty })" />
         </div>
         <div class="form-group">
             <label>Job Title</label>
             <input type="text" value="@Entry.Title"
                    @onchange="e => UpdateEntry(Entry with { Title = e.Value?.ToString() ?? string.Empty })" />
         </div>
     </div>
     <div class="form-row">
         <div class="form-group">
             <label>Start Date</label>
             <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                    @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
         </div>
         <div class="form-group">
             <label>End Date</label>
             <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                    disabled="@IsCurrent"
                    @onchange="e => UpdateEntry(Entry with { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null })" />
             <label class="checkbox-label">
                 <input type="checkbox" checked="@IsCurrent"
                        @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                 Currently working here
             </label>
         </div>
     </div>
     <div class="form-group">
         <label>Description</label>
         <textarea rows="3" value="@Entry.Description"
                   @onchange="e => UpdateEntry(Entry with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
     </div>
     @if (CanRemove)
     {
         <button type="button" class="btn-danger" @onclick="OnRemove">Remove</button>
     }
 </div>

 @code {
     [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
     [Parameter] public bool CanRemove { get; set; }
     [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
     [Parameter] public EventCallback OnRemove { get; set; }

     private bool IsCurrent => Entry.EndDate == null;

     private void UpdateEntry(WorkEntry updated) => OnEntryChanged.InvokeAsync(updated);

     private void ToggleCurrent(bool isCurrent)
     {
         var updated = isCurrent
             ? Entry with { EndDate = null }
             : Entry with { EndDate = DateTime.Today };
         OnEntryChanged.InvokeAsync(updated);
     }
 }

